package dental.flow.api.adapters.rest.out.persistence.repository;
import dental.flow.api.adapters.rest.out.persistence.entity.*; import dental.flow.api.boot.exception.BusinessException; import dental.flow.api.domain.inventory.*; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import java.math.BigDecimal; import java.time.LocalDateTime; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class InventoryRepositoryImplTest {
 @Mock InventoryProductJpaRepository products; @Mock EquipmentJpaRepository equipment; @Mock StockMovementJpaRepository movements; @InjectMocks InventoryRepositoryImpl repository;
 @Test void shouldPersistFindAndListProducts(){InventoryProductEntity entity=productEntity();when(products.saveAndFlush(any())).thenAnswer(i->{InventoryProductEntity e=i.getArgument(0);e.setId(1L);return e;});InventoryProduct domain=new InventoryProduct(3L,"Luva","UN",new BigDecimal("5"),BigDecimal.TEN,BigDecimal.ONE,true);assertEquals(1L,repository.saveProduct(domain).getId());when(products.findByIdAndClinicId(1L,3L)).thenReturn(Optional.of(entity));when(products.findByClinicIdOrderByName(3L)).thenReturn(List.of(entity));when(products.findByClinicIdAndActiveOrderByName(3L,true)).thenReturn(List.of(entity));when(products.existsByClinicIdAndNameIgnoreCaseAndIdNot(3L,"Luva",-1L)).thenReturn(true);assertTrue(repository.findProduct(1L,3L).isPresent());assertEquals(1,repository.listProducts(3L,null).size());assertEquals(1,repository.listProducts(3L,true).size());assertTrue(repository.productNameExists(3L,"Luva",null));}
 @Test void shouldApplyEveryMovementAndRejectNegativeStock(){InventoryProductEntity entity=productEntity();when(products.findLockedByIdAndClinicId(1L,3L)).thenReturn(Optional.of(entity));when(movements.saveAndFlush(any())).thenAnswer(i->{StockMovementEntity e=i.getArgument(0);e.setId(9L);return e;});assertEquals("ENTRADA",repository.moveStock(1L,3L,7L,"ENTRADA",new BigDecimal("2"),"Compra").type());assertEquals(new BigDecimal("12"),entity.getCurrentStock());assertEquals("SAIDA",repository.moveStock(1L,3L,7L,"SAIDA",new BigDecimal("3"),null).type());assertEquals("AJUSTE",repository.moveStock(1L,3L,7L,"AJUSTE",new BigDecimal("4"),null).type());assertThrows(BusinessException.class,()->repository.moveStock(1L,3L,7L,"SAIDA",new BigDecimal("5"),null));assertThrows(BusinessException.class,()->repository.moveStock(1L,3L,7L,"INVALIDO",BigDecimal.ONE,null));}
 @Test void shouldListMovementsAndHandleMissingProduct(){InventoryProductEntity entity=productEntity();StockMovementEntity movement=new StockMovementEntity();movement.setId(2L);movement.setProductId(1L);movement.setUserId(7L);movement.setType("ENTRADA");movement.setQuantity(BigDecimal.ONE);movement.setUnitCostAtTime(new BigDecimal("5"));movement.setReason("Compra");movement.setOccurredAt(LocalDateTime.now());when(products.findByIdAndClinicId(1L,3L)).thenReturn(Optional.of(entity));when(movements.findByProductIdOrderByOccurredAtDesc(1L)).thenReturn(List.of(movement));assertEquals(1,repository.listMovements(1L,3L).size());when(products.findByIdAndClinicId(2L,3L)).thenReturn(Optional.empty());assertThrows(BusinessException.class,()->repository.listMovements(2L,3L));}
 @Test void shouldPersistFindAndListEquipment(){EquipmentEntity entity=new EquipmentEntity();entity.setId(4L);entity.setClinicId(3L);entity.setName("Raio X");entity.setDescription("Digital");entity.setAcquisitionValue(new BigDecimal("1000"));entity.setUsefulLifeUses(100);entity.setCompletedUses(3);entity.setCostPerUse(new BigDecimal("10"));entity.setActive(true);when(equipment.saveAndFlush(any())).thenReturn(entity);when(equipment.findByIdAndClinicId(4L,3L)).thenReturn(Optional.of(entity));when(equipment.findByClinicIdOrderByName(3L)).thenReturn(List.of(entity));when(equipment.findByClinicIdAndActiveOrderByName(3L,true)).thenReturn(List.of(entity));when(equipment.existsByClinicIdAndNameIgnoreCaseAndIdNot(3L,"Raio X",4L)).thenReturn(true);Equipment item=new Equipment(3L,"Raio X","Digital",new BigDecimal("1000"),100,3,true);item.setId(4L);assertEquals(4L,repository.saveEquipment(item).getId());assertTrue(repository.findEquipment(4L,3L).isPresent());assertEquals(1,repository.listEquipment(3L,null).size());assertEquals(1,repository.listEquipment(3L,true).size());assertTrue(repository.equipmentNameExists(3L,"Raio X",4L));}
 private InventoryProductEntity productEntity(){InventoryProductEntity e=new InventoryProductEntity();e.setId(1L);e.setClinicId(3L);e.setName("Luva");e.setUnit("UN");e.setUnitCost(new BigDecimal("5"));e.setCurrentStock(BigDecimal.TEN);e.setMinimumStock(BigDecimal.ONE);e.setActive(true);return e;}
}
